## Code Example
```javascript
// Simulate flag resolution path under concurrent load
async function resolveFlag(userId, flagKey) {
  const cached = await redis.get(`flag:${flagKey}`);
  if (cached !== null) {
    metrics.increment('flag_cache_hit');
    return JSON.parse(cached);
  }
  const flag = await mongo.flags.findOne({ key: flagKey });
  await redis.setex(`flag:${flagKey}`, 300, JSON.stringify(flag));
  metrics.increment('flag_cache_miss');
  return flag;
}
```

